1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	
41	const FIRST_INSURANCE_SURCHARGE = 0.1;
42	
43	const BASE_PREMIUMS: Record<string, number> = {
44	  sword: 100,
45	  amulet: 60,
46	  staff: 80,
47	  potion: 40,
48	  rune: 25,
49	  moonstone: 25,
50	};
51	
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	
55	const LOYALTY_DISCOUNT = 0.2;
56	const FOLLOW_UP_DISCOUNT = 0.15;
57	const LOYALTY_YEARS = 2;
58	const CURSE_SURCHARGE = 0.5;
59	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	
62	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
63	  values.reduce((total, value) => total + amountOf(value), 0);
64	
65	// Counts only need a `type`, so anything that names one can be tallied — both
66	// the insured items and the item types a claim's damages name.
67	const countByType = (typed: { type: string }[]): Map<string, number> =>
68	  typed.reduce(
69	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
70	    new Map<string, number>(),
71	  );
72	
73	const basePremiumOf = (type: string): number => {
74	  const basePremium = BASE_PREMIUMS[type];
75	  if (basePremium === undefined) throw new Error(`unknown item type: ${type}`);
76	  return basePremium;
77	};
78	
79	const alikeItemsBasePremium = (type: string, count: number): number =>
80	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOf(type);
81	
82	const policyBasePremium = (items: Item[]): number =>
83	  sumOf([...countByType(items)], ([type, count]) =>
84	    alikeItemsBasePremium(type, count),
85	  );
86	
87	// Deliberately `amount + amount * rate`, not `amount * (1 + rate)`:
88	// `1 + 0.1` is inexact in binary floating point, so the latter yields
89	// 110.00000000000001 for 100 G. Since premiums round UP (in MHPCO's favor),
90	// that epsilon would overcharge by a whole Gold piece.
91	const withFirstInsuranceSurcharge = (amount: number): number =>
92	  amount + amount * FIRST_INSURANCE_SURCHARGE;
93	
94	// "In the MHPCO's favor" means opposite directions on either side of the
95	// ledger: money coming in rounds up, money going out rounds down.
96	const roundPremiumInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
97	const roundPayoutInMHPCOsFavor = (payout: number): number => Math.floor(payout);
98	
99	const isHighlyEnchanted = (item: Item): boolean =>
100	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
101	
102	// Both surcharges are a rate on the item's *own* base premium — never on the
103	// policy base, which may have been reduced by a block discount.
104	const surchargeOn = (item: Item, rate: number): number =>
105	  basePremiumOf(item.type) * rate;
106	
107	const curseSurcharge = (item: Item): number =>
108	  item.cursed ? surchargeOn(item, CURSE_SURCHARGE) : 0;
109	
110	const highEnchantmentSurcharge = (item: Item): number =>
111	  isHighlyEnchanted(item) ? surchargeOn(item, HIGH_ENCHANTMENT_SURCHARGE) : 0;
112	
113	const itemSurchargesTotal = (items: Item[]): number =>
114	  sumOf(items, (item) => curseSurcharge(item) + highEnchantmentSurcharge(item));
115	
116	const isLoyal = (customer: Customer): boolean =>
117	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
118	
119	// Like the surcharges, the loyalty discount is a rate on the policy base —
120	// not on the base already grown by the first-insurance surcharge.
121	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
122	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT : 0;
123	
124	const isFollowUpContract = (previousContracts: number): boolean =>
125	  previousContracts > 0;
126	
127	const followUpContractDiscount = (
128	  policyBase: number,
129	  previousContracts: number,
130	): number =>
131	  isFollowUpContract(previousContracts) ? policyBase * FOLLOW_UP_DISCOUNT : 0;
132	
133	const quotePremium = (
134	  items: Item[],
135	  customer: Customer,
136	  previousContracts: number,
137	): number => {
138	  const policyBase = policyBasePremium(items);
139	  // Not a delta: this is the policy base *after* the policy-wide surcharge and
140	  // discounts, which the item surcharges and the flat fee are then added to.
141	  const adjustedPolicyBase =
142	    withFirstInsuranceSurcharge(policyBase) -
143	    loyaltyDiscount(policyBase, customer) -
144	    followUpContractDiscount(policyBase, previousContracts);
145	  return roundPremiumInMHPCOsFavor(
146	    adjustedPolicyBase + itemSurchargesTotal(items) + PROCESSING_FEE,
147	  );
148	};
149	
150	const DEDUCTIBLE = 100;
151	const CAP_MULTIPLE = 2;
152	
153	const INSURANCE_VALUES: Record<string, number> = {
154	  sword: 1000,
155	  amulet: 600,
156	  staff: 800,
157	  potion: 400,
158	  rune: 250,
159	  moonstone: 250,
160	};
161	
162	const insuranceSum = (items: Item[]): number =>
163	  sumOf(items, (item) => INSURANCE_VALUES[item.type]);
164	
165	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
166	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
167	
168	const isHighlyEnchantedForClaims = (item: Item): boolean =>
169	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
170	
171	// The special clause reduces the damage amount first; the deductible is taken
172	// from what the clause leaves.
173	const damagePayout = (damage: Damage, damagedItem: Item): number => {
174	  const reimbursed = isHighlyEnchantedForClaims(damagedItem)
175	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
176	    : damage.amount;
177	  return reimbursed - DEDUCTIBLE;
178	};
179	
180	// The cap is twice the policy's insurance sum — driven by the insured items'
181	// values alone, never by the premium the customer happened to be quoted.
182	const policyCap = (insuredItems: Item[]): number =>
183	  insuranceSum(insuredItems) * CAP_MULTIPLE;
184	
185	// Placeholder: a damage entry naming an item the policy does not cover is not
186	// yet rejected — the pending "item not part of the policy" test will drive that
187	// guard, and this cast is what it will replace.
188	const damagedItemIn = (insuredItems: Item[], damage: Damage): Item =>
189	  insuredItems.find((item) => item.type === damage.itemType) as Item;
190	
191	// A claim never pays more than the policy's cap has left, so its result is
192	// both the payout and the cap the *next* claim on that policy starts from.
193	interface ClaimResult {
194	  payout: number;
195	  remainingCap: number;
196	}
197	
198	// A policy covering one sword answers for one damaged sword. More entries of a
199	// type than the policy insures means the claim describes items that are not
200	// covered, so the whole claim is rejected.
201	const damagedTypes = (damages: Damage[]): { type: string }[] =>
202	  damages.map((damage) => ({ type: damage.itemType }));
203	
204	const rejectOverClaimedTypes = (
205	  damages: Damage[],
206	  insuredItems: Item[],
207	): void => {
208	  const insuredCounts = countByType(insuredItems);
209	  for (const [type, damaged] of countByType(damagedTypes(damages))) {
210	    if (damaged > (insuredCounts.get(type) ?? 0)) {
211	      throw new Error(`policy does not cover ${damaged} damaged ${type}(s)`);
212	    }
213	  }
214	};
215	
216	const claimResult = (
217	  incident: Incident,
218	  insuredItems: Item[],
219	  capRemaining: number,
220	): ClaimResult => {
221	  rejectOverClaimedTypes(incident.damages, insuredItems);
222	  const desiredPayout = sumOf(incident.damages, (damage) =>
223	    damagePayout(damage, damagedItemIn(insuredItems, damage)),
224	  );
225	  const payout = roundPayoutInMHPCOsFavor(Math.min(desiredPayout, capRemaining));
226	  return { payout, remainingCap: capRemaining - payout };
227	};
228	
229	const isQuote = (step: Step): boolean => step.op === "quote";
230	
231	// A quote's premium depends on how many contracts precede it, so each step is
232	// run against the quotes that came before it rather than a mutable counter.
233	const contractsBefore = (steps: Step[], index: number): number =>
234	  steps.slice(0, index).filter(isQuote).length;
235	
236	export const runScenario = (scenario: Scenario): ScenarioResult => {
237	  const insuredItemsOf = (policyIndex: number): Item[] => {
238	    const policyStep = scenario.steps[policyIndex];
239	    if (policyStep?.op !== "quote") {
240	      throw new Error(`step ${policyIndex} is not a quote`);
241	    }
242	    return policyStep.items;
243	  };
244	
245	  // Each policy's cap is consumed across successive claims, so the remaining
246	  // cap is the one piece of state that has to survive from step to step. It is
247	  // threaded through the claim branch alone — a quote neither reads nor writes
248	  // it, and so is never handed a placeholder cap to ignore.
249	  const capRemainingByPolicy = new Map<number, number>();
250	  const settleClaim = (policyIndex: number, incident: Incident): ClaimResult => {
251	    const insuredItems = insuredItemsOf(policyIndex);
252	    const capRemaining =
253	      capRemainingByPolicy.get(policyIndex) ?? policyCap(insuredItems);
254	    const result = claimResult(incident, insuredItems, capRemaining);
255	    capRemainingByPolicy.set(policyIndex, result.remainingCap);
256	    return result;
257	  };
258	
259	  const runStep = (step: Step, index: number): StepResult =>
260	    step.op === "quote"
261	      ? {
262	          premium: quotePremium(
263	            step.items,
264	            scenario.customer,
265	            contractsBefore(scenario.steps, index),
266	          ),
267	        }
268	      : settleClaim(step.policy, step.incident);
269	
270	  return { results: scenario.steps.map(runStep) };
271	};
