    (counts, value) =>
      counts.set(keyOf(value), (counts.get(keyOf(value)) ?? 0) + 1),
    new Map<string, number>(),
  );

const itemType = (item: Item): string => item.type;

const basePremiumOf = (type: string): number => {
  const basePremium = BASE_PREMIUMS[type];
  if (basePremium === undefined) throw new Error(`unknown item type: ${type}`);
  return basePremium;
};
