const isEnchantedEnoughForHalvedReimbursement = (item: Item): boolean =>
  enchantmentOf(item) >= HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL;

// The special clause reduces the damage amount first; the deductible is taken
